#include <iostream>
#include <string>
#include <stdexcept>
using namespace std;

int main() {
    string word = "{word}";
    try {
        int n = stoi(word);
        cout << "挖到的数字是 " << n << " 喵" << endl;
    } catch (const invalid_argument& e) {
        cout << word << " 这串字不是数字喵：" << e.what() << endl;
    }
    return 0;
}
